import 'server-only'
import type { ClienteRedisDeLeitura } from '../adaptadores/sessao-redis.js'
export async function renovar(cliente: ClienteRedisDeLeitura, chave: string, valor: string): Promise<void> {
  await (cliente as unknown as { set(k: string, v: string, o: { PX: number }): Promise<unknown> }).set(chave, valor, { PX: 3_600_000 })
}

import 'server-only'
import { createClient } from 'redis'
export async function renovar(url: string, chave: string, valor: string): Promise<void> {
  const c = await createClient({ url }).connect()
  await c.set(chave, valor)
}
